"""Exact normalized phrase routes with conflict abstention; no model or network calls."""
import re

RULES = [{'id': 'phrase-01', 'phrase': 'inure to the benefit of', 'label': 'Assignments', 'development_support': 14, 'development_correct': 14}, {'id': 'phrase-02', 'phrase': 'consent of the other', 'label': 'Assignments', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-03', 'phrase': 'agreement may be executed in', 'label': 'Counterparts', 'development_support': 27, 'development_correct': 27}, {'id': 'phrase-04', 'phrase': 'shall constitute one and the same', 'label': 'Counterparts', 'development_support': 20, 'development_correct': 20}, {'id': 'phrase-05', 'phrase': 'counterparts each of which shall', 'label': 'Counterparts', 'development_support': 19, 'development_correct': 19}, {'id': 'phrase-06', 'phrase': 'parties hereto with respect to the', 'label': 'Entire Agreements', 'development_support': 10, 'development_correct': 10}, {'id': 'phrase-07', 'phrase': 'entire agreement and understanding', 'label': 'Entire Agreements', 'development_support': 10, 'development_correct': 10}, {'id': 'phrase-08', 'phrase': 'the entire agreement between the parties', 'label': 'Entire Agreements', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-09', 'phrase': 'fees and expenses of', 'label': 'Expenses', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-10', 'phrase': 'be governed by and construed', 'label': 'Governing Laws', 'development_support': 19, 'development_correct': 19}, {'id': 'phrase-11', 'phrase': 'by the laws of the state', 'label': 'Governing Laws', 'development_support': 14, 'development_correct': 14}, {'id': 'phrase-12', 'phrase': 'this agreement shall be governed', 'label': 'Governing Laws', 'development_support': 13, 'development_correct': 13}, {'id': 'phrase-13', 'phrase': 'writing and shall be', 'label': 'Notices', 'development_support': 15, 'development_correct': 15}, {'id': 'phrase-14', 'phrase': 'mail return receipt requested', 'label': 'Notices', 'development_support': 10, 'development_correct': 10}, {'id': 'phrase-15', 'phrase': 'invalid illegal or unenforceable', 'label': 'Severability', 'development_support': 10, 'development_correct': 10}, {'id': 'phrase-16', 'phrase': 'if any provision of this agreement', 'label': 'Severability', 'development_support': 8, 'development_correct': 8}, {'id': 'phrase-17', 'phrase': 'of this agreement is', 'label': 'Severability', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-18', 'phrase': 'the representations and warranties', 'label': 'Survival', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-19', 'phrase': 's obligations under this', 'label': 'Survival', 'development_support': 9, 'development_correct': 9}, {'id': 'phrase-20', 'phrase': 'shall commence on the', 'label': 'Terms', 'development_support': 11, 'development_correct': 11}, {'id': 'phrase-21', 'phrase': 'term of this agreement shall', 'label': 'Terms', 'development_support': 8, 'development_correct': 8}]

def classify(text, labels):
    if not isinstance(text, str) or not text.strip() or len(text) > 200_000:
        return None
    normalized = ' ' + ' '.join(re.findall(r"\b\w+\b", text.casefold())) + ' '
    matches = [rule for rule in RULES if ' '+rule['phrase']+' ' in normalized]
    targets = {rule['label'] for rule in matches}
    if len(targets) != 1 or next(iter(targets)) not in labels:
        return None
    label = next(iter(targets))
    return {'label':label, 'matched_rule':','.join(rule['id'] for rule in matches)}
